# Draft: Heart of Ruin (stun dash engager), Prism, Marcella, Cassi/Issac, Varg,
# then Stellar/Willow, otherwise random.
# Every champion casts its stun slot (slot_stun > 0) FIRST to open fights, then
# its other slot, then basic attacks the weakest enemy in range.
# Heart of Ruin is the diver: it engages at worse odds, sets the team target,
# and hunts that target. The others follow the target only when they can see it.
# Farming: pick the nearest gem-rich camp group that no ally has claimed.
# Avoid golem and monolith groups until late, when allies are nearby.
# Capture cleared camps, tribute at 25+ gems, recall when low, shop on spawn.

def use_slot(s, u, t, d):
    if ability_ready(s):
        if slot_is_dash(s):
            if d > 1 and d <= slot_range(s) + 2:
                dash_towards(s, t)
        elif slot_is_shield(s):
            cast_self(s)
        elif slot_is_heal(s):
            cast_self(s)
        elif slot_is_reset(s):
            if not can_attack():
                cast_self(s)
        elif d <= slot_range(s):
            cast_at_unit(s, u)

def camp_slot(s, u, d):
    if ability_ready(s):
        if slot_is_damage(s) or slot_is_aoe(s):
            if d <= slot_range(s):
                cast_at_unit(s, u)
        elif slot_is_reset(s):
            if not can_attack():
                cast_self(s)

