# PLAN: per-champion roles
#  Draft: Heart of Ruin (hunter, stun dash), Ryth (AoE farmer), Vesper Vale (support),
#         then Varg (hunter), then Cassi/Issac, else random.
#  HUNTER (Heart of Ruin / Varg / Vendetta): focuses the weakest visible enemy, sets
#         the team target, dashes in when the local fight is not lost. Kills take the
#         victim's gems. Farms heavy camps (golems allowed) when no enemy is visible.
#  FARMER (everyone else): claims the nearest unclaimed non-monolith camp. Avoids
#         golems early. Fights enemies only when local strength favours us. Tributes at 40 gems.
#  SUPPORT (Vesper Vale / Willow): heals the weakest ally first, buys health shards,
#         farms easy camps, and tributes early (20 gems) to bank score safely.
#  All roles: heal on spawn, retreat home when low, never touch monoliths,
#         dump every carried gem before round 2000.

def hit(t):
    if ability_ready(0) and (slot_is_damage(0) or slot_is_stun(0) or slot_is_aoe(0)) and distance(position(), unit_position(t)) <= slot_range(0):
        cast_at_unit(0, t)
    elif ability_ready(1) and (slot_is_damage(1) or slot_is_stun(1) or slot_is_aoe(1)) and distance(position(), unit_position(t)) <= slot_range(1):
        cast_at_unit(1, t)
    if can_attack():
        if i_am_ranged():
            if distance(position(), unit_position(t)) <= 3:
                attack(t)
        else:
            if distance(position(), unit_position(t)) <= 1:
                attack(t)
    if not can_attack():
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(t)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(t)

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_varg()):
        pick(champ_varg())
    elif available(pool, champ_cassi_issac()):
        pick(champ_cassi_issac())
    else:
        pick(random_champion(pool))
    end_turn()

let support = i_am(champ_vesper_vale()) or i_am(champ_willow())
let hunter = i_am(champ_heart_of_ruin()) or i_am(champ_varg()) or i_am(champ_vendetta())

if not alive():
    if gold() >= 30:
        if support:
            buy(shard(stat_health()), floor(gold() / 30))
        else:
            buy(shard(stat_strength()), floor(gold() / 30))
    end_turn()

if channeling():
    end_turn()

let me = position()
let hp = health() / max_health()
let home = spawn_region(ally())

if contains(home, me) and gold() >= 30:
    if support:
        buy(shard(stat_health()), floor(gold() / 30))
    else:
        buy(shard(stat_strength()), floor(gold() / 30))

let foes = enemies_visible()
let near = nearest(foes)
let foe = weakest(foes)
let inr = weakest(filter(foes, in_attack_range()))

# heal on spawn
if contains(home, me) and hp < 0.9:
    if exists(inr):
        hit(inr)
    end_turn()

# low health: go home
if hp < 0.3:
    if exists(inr):
        hit(inr)
    if exists(near):
        move_towards(closest(home))
    else:
        recall()
    end_turn()

# support role: heal first
if support:
    let mate = weakest(allies_visible())
    if exists(mate) and unit_health_frac(mate) < 0.7:
        if ability_ready(0) and slot_is_heal(0):
            cast_at_unit(0, mate)
        elif ability_ready(1) and slot_is_heal(1):
            cast_at_unit(1, mate)

let gm = gems()
let alt = closest(altars())
let tribute_now = gm >= 40 or (support and gm >= 20) or (round_number() > 1850 and gm > 0)

if tribute_now and exists(alt):
