    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health when in danger, recall only once clear
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate: a long retreat's dash search can push the turn past 100k
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: cast damage/stun at a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0):
            cast_at_unit(0, near_foe)
        if ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1):
            cast_at_unit(1, near_foe)

let enemy = weakest( filter( foes, in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    # attack reset: a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach; else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# nothing tributed by round 800: go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

# spread: skip camp groups that allies already claim (claim-spread route)
let spread = minus( goals, claimed_by_allies() )
let goal = closest(spread)
# every open group is claimed by an ally: walk toward the nearest group anyway
if not exists(goal):
    move_towards( closest(goals) )
    end_turn()

# bank before a dangerous group (group_threat >= 240: elk 60, wolf 20 per camp)
# fuel guard: the bank walk is a second distance query this turn
if gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group that is not cleared yet, the closest goal is our own tile: walk to the
# nearest living camp instead (not a monolith or golem), so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# optional dash toward a far camp goal, only with fuel to spare
if distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
# claim the group we walk to so allies pick other camps
claim(goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# PLAN (vision axis: bushes, wards, fog, tile-targeted AoE):
# - Ward the bush next to us whenever we stand near a camp we are farming or a fight is
#   likely, so we see the camp group and the approach before the enemy sees us.
# - Area abilities are cast at the target's TILE (cast_at_tile), so they land on
#   enemies standing in bushes or beyond our vision edge.
# - Keep v1 role logic: stun opener, team focus, basic > reset > basic, shields,
#   ranged kiting away from walls, rich-group choice, safe tribute.
# - Fight only with vision: enemies behind walls/bushes are ignored unless they are
#   inside attack reach, so we do not walk blind into a group.

def fight(t):
    set_team_target(t)
    if ability_ready(1) and slot_stun(1) > 0 and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
        if slot_is_dash(1):
            if fuel_remaining() > 30000:
                dash_towards(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    elif ability_ready(0) and slot_stun(0) > 0 and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            if fuel_remaining() > 30000:
                dash_towards(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    if i_am_ranged() and can_move() and distance(position(), unit_position(t)) <= 1 and not contains(wallring, position()):
        move_away_from(unit_position(t))
    if can_attack() and (distance(position(), unit_position(t)) <= 1 or (i_am_ranged() and distance(position(), unit_position(t)) <= 3)):
        attack(t)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(t)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(t)
    if ability_ready(0) and slot_is_aoe(0) and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
        cast_at_tile(0, unit_position(t))
    elif ability_ready(0) and slot_is_damage(0) and distance(position(), unit_position(t)) <= slot_range(0):
        cast_at_unit(0, t)
    if ability_ready(1) and slot_is_aoe(1) and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
        cast_at_tile(1, unit_position(t))
    elif ability_ready(1) and slot_is_damage(1) and distance(position(), unit_position(t)) <= slot_range(1):
        cast_at_unit(1, t)
    if ability_ready(0) and slot_is_shield(0):
        cast_self(0)
    if ability_ready(1) and slot_is_shield(1):
        cast_self(1)
    if can_move() and can_attack():
        if distance(position(), unit_position(t)) > 1:
            if not (i_am_ranged() and distance(position(), unit_position(t)) <= 3):
                move_towards(unit_position(t))

if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    else:
        pick(random_champion(pool))
    end_turn()

# ---- shopping (role-based stats) ----
if (not alive()) or contains(spawn_region(ally()), position()):
    if gold() >= 30:
        if round_number() < 250:
            buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
        elif i_am(champ_heart_of_ruin()):
            buy(shard_of(family_bruiser(), stat_health()), floor(gold() / 30))
        elif i_am(champ_vesper_vale()) or i_am(champ_vendetta()):
            buy(shard_of(family_power(), stat_strength()), floor(gold() / 30))
        elif i_am(champ_marcella()) or i_am(champ_ryth()) or i_am(champ_prism()) or i_am(champ_cassi_issac()) or i_am(champ_tavi()) or i_am(champ_stellar()):
            buy(shard_of(family_power(), stat_focus()), floor(gold() / 30))
        else:
            buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

if not alive():
    end_turn()
if channeling():
    end_turn()

if i_am(champ_heart_of_ruin()):
    set_priority(3)
else:
    set_priority(1)

keep wallring = ring(walls(), 1)
keep monogroup = group_tiles(monolith_tiles())
keep safealt = minus(altars(), ring(monolith_tiles(), 5))
keep campset = minus(camp_spawn_tiles(), monogroup)
keep richset = minus(rich_spawns(15), monogroup)
keep bushset = bushes()

let me = position()
let hp = health() / max_health()
let foes = enemies_visible()
let foe = nearest(foes)
let nfoes = count(foes)

# ---- survival ----
if hp < 0.35 and nfoes > 0 and gems() < 10:
    if in_danger():
        move_away_from(unit_position(foe))
        end_turn()
if hp < 0.4 and not in_danger():
    recall()
    end_turn()

# ---- tribute ----
let alt = closest(safealt)
if gems() >= 35 or (gems() >= 10 and nfoes > 0) or (gems() > 0 and round_number() > 1900):
    if exists(alt):
        if distance(me, alt) <= 1:
            tribute(alt)
            end_turn()
        if nfoes == 0:
            move_towards(alt)
            end_turn()
    else:
        let alt2 = closest(altars())
        if distance(me, alt2) <= 1:
            tribute(alt2)
            end_turn()
        if nfoes == 0:
            move_towards(alt2)
            end_turn()

# ---- fight (only what we can see and reach) ----
if nfoes > 0:
    let inr = weakest(filter(foes, in_attack_range()))
    let tt = team_target()
    let ttok = exists(tt) and unit_health_frac(tt) > 0 and distance(me, unit_position(tt)) <= 5
    if ttok:
        fight(tt)
        end_turn()
    elif exists(inr):
        fight(inr)
        end_turn()
    elif distance(me, unit_position(foe)) <= 5 and (hp > 0.6 or allies_within(4) > 0):
        fight(foe)
        end_turn()

# ---- capture ----
let cap = closest(capturable_spawns())
if exists(cap):
    move_towards(cap)
    end_turn()

# ---- camps (ward the bush beside us while farming) ----
let camp = nearest(camps_visible())
if exists(camp):
    let mono = closest(monolith_tiles())
    let monook = round_number() >= 1000 and allies_within(5) >= 2 and hp > 0.6
    if distance(unit_position(camp), mono) > 6 or monook:
        if nfoes == 0 and distance(me, unit_position(camp)) <= 4:
            let wb = first(filter(bushset, within(2, me)))
            if exists(wb):
                place_ward(wb)
        if can_attack() and (distance(me, unit_position(camp)) <= 1 or (i_am_ranged() and distance(me, unit_position(camp)) <= 3)):
            attack(camp)
            if ability_ready(0) and slot_is_reset(0):
                cast_self(0)
                attack(camp)
            if ability_ready(0) and slot_is_shield(0) and in_danger():
                cast_self(0)
            if ability_ready(1) and slot_is_shield(1) and in_danger():
                cast_self(1)
            end_turn()

let near = closest(campset)
let richc = closest(richset)
if exists(richc) and distance(me, richc) <= distance(me, near) + 6:
    claim(richc)
    move_towards(richc)
    end_turn()
if exists(near):
    claim(near)
    move_towards(near)
    end_turn()
if turns_idle() > 3:
    move_towards(closest(camp_spawn_tiles()))

# PLAN: team coordination through shared memory.
# - Roles: on the first turn each champion reads byte 7 as its role index and writes
#   role+1, so champions get ids 0,1,2,... without the draft bot's help.
# - Pairs: even roles are LEADERS. A leader picks a camp (rich if only a few tiles
#   farther than the nearest), skipping groups claimed by allies, and claims it.
#   Odd roles are BUDDIES: they join the nearest ally-claimed camp, so we farm in
#   twos and fight 2v1.
# - Focus fire: whoever engages names the target with set_team_target. Allies
#   prefer the team target when it is visible and near.
# - Fight micro: stun opener (dash if the stun is a dash), damage ability, basic
#   attack, then a self-cast reset and a second attack. Ranged champions step away
#   from adjacent enemies when hurt. Shield at mid health.
# - Monolith: after MONO_ROUND roles 0-2 claim it and gather; they hit it only
#   when 2+ allies are close.
# - Shopping: Treasure shards early, then Bruiser Strength, with some random_stat
#   shards mixed in for variety.

def fight(t):
  set_team_target(t)
  if hp < 0.7 and ability_ready(0) and slot_is_shield(0):
    cast_self(0)
  elif hp < 0.7 and ability_ready(1) and slot_is_shield(1):
    cast_self(1)
  if ability_ready(1) and slot_stun(1) > 0 and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
    if slot_is_dash(1):
      dash_towards(1, unit_position(t))
    elif slot_radius(1) > 0:
      cast_at_tile(1, unit_position(t))
    else:
      cast_at_unit(1, t)
  elif ability_ready(0) and slot_stun(0) > 0 and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
    if slot_is_dash(0):
      dash_towards(0, unit_position(t))
    elif slot_radius(0) > 0:
      cast_at_tile(0, unit_position(t))
    else:
      cast_at_unit(0, t)
  elif ability_ready(0) and slot_is_aoe(0) and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
    cast_at_tile(0, unit_position(t))
  elif ability_ready(1) and slot_is_aoe(1) and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
    cast_at_tile(1, unit_position(t))
  elif ability_ready(0) and slot_is_damage(0) and distance(position(), unit_position(t)) <= slot_range(0):
    cast_at_unit(0, t)
  elif ability_ready(1) and slot_is_damage(1) and distance(position(), unit_position(t)) <= slot_range(1):
    cast_at_unit(1, t)
  if distance(position(), unit_position(t)) <= 1 or (i_am_ranged() and distance(position(), unit_position(t)) <= 3):
    if i_am_ranged() and distance(position(), unit_position(t)) <= 1 and hp < KITE_HP and can_move():
      move_away_from(unit_position(t))
    else:
      attack(t)
      if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
        attack(t)
      elif ability_ready(1) and slot_is_reset(1):
        cast_self(1)
        attack(t)
  else:
    if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0:
      dash_towards(0, unit_position(t))
    elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0:
      dash_towards(1, unit_position(t))
    move_towards(unit_position(t))
  end_turn()

def go_tribute(a):
  if distance(position(), a) <= 1:
    tribute(a)
  else:
    move_towards(a)
  end_turn()

def go_camp(g):
  claim(g)
  move_towards(g)
  end_turn()

if is_draft():
  let pool = unpicked_champions()
  if available(pool, champ_vesper_vale()):
    pick(champ_vesper_vale())
  elif available(pool, champ_heart_of_ruin()):
    pick(champ_heart_of_ruin())
  elif available(pool, champ_marcella()):
    pick(champ_marcella())
  elif available(pool, champ_vendetta()):
    pick(champ_vendetta())
  elif available(pool, champ_ryth()):
    pick(champ_ryth())
  else:
    pick(random_champion(pool))
  end_turn()

if not alive():
  if gold() >= 30:
    if round_number() < 250:
      buy(shard_of(family_treasure(), stat_strength()), 1)
    else:
      buy(shard_of(family_bruiser(), stat_strength()), 1)
  end_turn()

if channeling():
  end_turn()

# tunable constants
keep RECALL_HP = 0.4
keep KITE_HP = 0.85
keep ENGAGE_R = 6
keep OUTNUM = 1
keep BAG = 25
keep RICH_SLACK = 5
keep MONO_ROUND = 1000

# role assignment via byte 7
keep firstround = round_number()
keep myrole = read_shared(7)
if round_number() == firstround:
  write_shared(7, myrole + 1)

let me = position()
let hp = health() / max_health()
let foes = enemies_visible()
let foe = nearest(foes)
let tt = team_target()
let home = spawn_region(ally())

# shopping
if contains(home, me) and gold() >= 30:
  if round_number() < 250:
    buy(shard_of(family_treasure(), stat_strength()), 1)
  elif random_int(4) == 0:
    buy(shard(random_stat()), 1)
  else:
    buy(shard_of(family_bruiser(), stat_strength()), 1)

# heal at home
if contains(home, me) and hp < 0.9 and count(foes) == 0:
  end_turn()

# low health: get out, then recall
if hp < RECALL_HP:
  if exists(foe) and distance(me, unit_position(foe)) <= 4:
    move_away_from(unit_position(foe))
  elif not in_danger():
    recall()
  else:
    move_towards(closest(home))
  end_turn()

keep safealt = minus(altars(), ring(monolith_tiles(), 5))

# carrying gems with an enemy near: tribute at once
if gems() >= 5 and enemies_within(8) > 0 and hp < 0.8:
  if count(safealt) > 0:
    go_tribute(closest(safealt))
  else:
    go_tribute(closest(altars()))

# fights: focus the team target, avoid being badly outnumbered
if exists(foe):
  if distance(me, unit_position(foe)) <= ENGAGE_R and enemies_within(6) <= allies_within(6) + OUTNUM:
    if exists(tt) and unit_health_frac(tt) > 0 and distance(me, unit_position(tt)) <= ENGAGE_R:
      fight(tt)
    else:
      fight(foe)
  elif distance(me, unit_position(foe)) <= 4:
    move_away_from(unit_position(foe))
    end_turn()

# bank a full bag
if gems() >= BAG or (gems() > 0 and round_number() > 1950):
  if count(safealt) > 0:
    go_tribute(closest(safealt))
  else:
    go_tribute(closest(altars()))

# capture cleared groups
let cap = closest(capturable_spawns())
if exists(cap) and distance(me, cap) <= 10:
  if distance(me, cap) == 0:
    end_turn()
  move_towards(cap)
  end_turn()

keep monos = group_tiles(monolith_tiles())
let nearmono = count(filter(monos, within(6, me))) > 0
let cv = weakest(filter(camps_visible(), in_attack_range()))

# team monolith take
if round_number() > MONO_ROUND and myrole < 3 and hp > 0.8 and count(monos) > 0:
  let mt = closest(monos)
  if exists(mt):
    claim(mt)
    if distance(me, mt) > 4:
      move_towards(mt)
      end_turn()
    if allies_within(5) >= 2 and exists(cv):
      if ability_ready(0) and slot_is_damage(0):
        cast_at_unit(0, cv)
      attack(cv)
      end_turn()
    end_turn()

# hit camps in range (never the monolith outside the team take)
if exists(cv) and not nearmono:
  if ability_ready(0) and slot_is_damage(0) and slot_stun(0) == 0:
    cast_at_unit(0, cv)
  elif ability_ready(1) and slot_is_damage(1) and slot_stun(1) == 0:
    cast_at_unit(1, cv)
  attack(cv)
  if ability_ready(0) and slot_is_reset(0):
    cast_self(0)
    attack(cv)
  elif ability_ready(1) and slot_is_reset(1):
    cast_self(1)
    attack(cv)
  end_turn()

# buddies join an ally's claimed camp
let pal = claimed_by_allies()
if floor(myrole / 2) * 2 != myrole and count(pal) > 0:
  let palc = closest(pal)
  if exists(palc):
    go_camp(palc)

# leaders choose: rich camp if only a few tiles farther than the nearest
keep camps0 = minus(camp_spawn_tiles(), monos)
keep rich = rich_spawns(12)
let live = minus(minus(camps0, respawning_visible_spawns()), pal)
let near = closest(live)
let rc = closest(minus(live, minus(live, rich)))
if exists(rc) and distance(me, rc) <= distance(me, near) + RICH_SLACK:
  go_camp(rc)
if exists(near):
  go_camp(near)

if gems() > 0:
  go_tribute(closest(altars()))
move_towards(closest(camps0))

# role-split v1 + group-up: frontliners (Vendetta, Vesper Vale, Tavi, Heart of Ruin) keep the tune-line behaviour.
# Backliners (everyone else) bank gems earlier (bag 12) and, when ranged, kite: step away from a
# close enemy champion before they attack, instead of trading in place.
# NEW (team coordination): backliners do not take a fight they would lose alone. When two or more
# enemy champions are visible within 6 and no ally is within 5, the backliner steps back out of
# reach (toward its team) instead of engaging, so the enemy's group arrival meets our group.
# Parent: tune-r-all-v2 (tune5-campreset + safe recall + monolith fallback + fuel guards).

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
