# MACRO PLAN (route & timing), built on Version 1 (the stronger line):
# 1) Early/mid (round <= 1200): spread the farm. Each champion claims its camp goal; the support roles
#    skip goals within 2 of an ally's claim, so the team clears more groups in parallel. They do this
#    only when the free goal is at most 8 tiles farther than the shared one.
# 2) Vendetta is the anchor/tank. It ignores claims and walks to the nearest goal, so it backs up whoever is there.
# 3) Late (round > 1200), only when not ahead: healthy champions with a light bag claim the nearest monolith group.
#    They walk there only when 2+ allies also claim it (3 together); otherwise they keep farming.
#    No camp claims are written in this phase, so the monolith claims persist and can add up.
# 4) Banking stays as in V1: 25-gem bag, bank before 240-threat groups, all-in tribute after round 1500.
# 5) VISION (new): while approaching a camp goal, drop a ward on a bush next to us. Bush interiors are
#    where enemies hide from vision, so the ward reveals the fog around the fight before it starts.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# walk to a camp goal (bank first before dangerous groups, finish half-cleared groups, dash on far trips)
def go_goal(g):
    if exists(g) and gems() >= 10 and group_threat(g) >= 240 and fuel_remaining() > 65000:
        let bank_altar = first( filter( altars(), within(1, position()) ) )
        if exists(bank_altar):
            tribute(bank_altar)
            end_turn()
        move_towards( closest(safe_altar_ring) )
        end_turn()
    if distance(g, position()) == 0:
        let live = nearest(camps)
        if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
            move_towards( unit_position(live) )
            end_turn()
    # VISION: ward a bush beside us when the goal is close, to see into the fog before the fight
    if exists(g) and distance(position(), g) <= 6 and fuel_remaining() > 50000:
        let ward_bush = first( filter( bushes(), within(2, position()) ) )
        if exists(ward_bush):
            place_ward(ward_bush)
    if exists(g) and distance(position(), g) > 2 and fuel_remaining() > 55000:
        if ability_ready(0) and slot_is_dash(0):
            dash_towards(0, g)
        if ability_ready(1) and slot_is_dash(1):
            dash_towards(1, g)
    move_towards( g )
    let camp2 = first( filter( camps, in_attack_range() ) )
    if exists(camp2):
        attack(camp2)
    set_priority( 1 + random_int(100) )
    end_turn()

# ---- draft ----
