# PLAN: "Vendetta spear" draft. Heart of Ruin engages with a stun dash, Vendetta
# dashes and resets, Marcella and Prism add damage and AoE, Cassi/Varg fill in.
# Shard spending: Heart of Ruin keeps buying Strength, the other champions buy a
# random stat each time (random_stat) to spread their build and avoid stalling
# on one stat.

def use_slot(s, u, t, d):
    if ability_ready(s):
        if slot_is_dash(s):
            if d > 1 and d <= slot_range(s) + 2:
                dash_towards(s, t)
        elif slot_is_shield(s):
            cast_self(s)
        elif slot_is_heal(s):
            cast_self(s)
        elif slot_is_reset(s):
            if not can_attack():
                cast_self(s)
        elif slot_is_aoe(s) and slot_radius(s) > 0:
            if d <= slot_range(s) + slot_radius(s):
                cast_at_tile(s, t)
        elif d <= slot_range(s):
            cast_at_unit(s, u)

def camp_slot(s, u, d):
    if ability_ready(s):
        if slot_is_damage(s) or slot_is_aoe(s):
            if d <= slot_range(s):
                cast_at_unit(s, u)
        elif slot_is_reset(s):
            if not can_attack():
                cast_self(s)

