# fights: focus the team target, avoid being badly outnumbered
if exists(foe):
  if distance(me, unit_position(foe)) <= 6 and enemies_within(6) <= allies_within(6) + 1:
    if exists(tt) and unit_health_frac(tt) > 0 and distance(me, unit_position(tt)) <= 6:
