# PLAN (ability-centred team, written from scratch)
# Draft: Heart of Ruin (stun dash), Ryth (AoE stun), Vesper Vale and Vendetta (resets),
#   then Marcella (damage). Every pick has a stun or a reset.
# Turn order: champions with a stun get higher priority, so the stun lands before allies burst.
# Fight micro, the same for every champion (roles come from the slot_* queries):
#   1. Stun opener first: a dash stun from range+1, an AoE stun with cast_at_tile, or a
#      targeted stun.
#   2. Then a dash to close the gap, or a damage / AoE nuke on the stunned target.
#   3. Shield when hurt in a fight. Heal the weakest ally below 60%, or yourself.
#   4. Basic attack, then self-cast the reset right after it and attack again.
#   5. Focus fire through the team target. Ranged champions step away from melee when hurt.
# Macro: buy shards, tribute at bag 30 at safe altars (away from monoliths; locked altars kept
#   as a fallback), recall at low HP only when not in danger, and prefer rich gem camps when
#   they are only a little farther than the nearest camp.

def dist_to(t):
    return distance(position(), unit_position(t))

def stun_ok(s, t):
    return ability_ready(s) and slot_stun(s) > 0 and ((slot_is_dash(s) and dist_to(t) <= slot_range(s) + 1) or ((not slot_is_dash(s)) and dist_to(t) <= slot_range(s)))

def dmg_ok(s, t):
    return ability_ready(s) and slot_stun(s) == 0 and (not slot_is_reset(s)) and (not slot_is_heal(s)) and (not slot_is_shield(s)) and ((slot_is_dash(s) and dist_to(t) >= 2 and dist_to(t) <= slot_range(s) + 1) or ((not slot_is_dash(s)) and (slot_is_damage(s) or slot_is_aoe(s)) and dist_to(t) <= slot_range(s)))

def shield_ok(s):
    return ability_ready(s) and slot_is_shield(s) and health() < max_health() * 0.85

def heal_ally_ok(s):
    return ability_ready(s) and slot_is_heal(s) and exists(weakest(allies_visible())) and unit_health_frac(weakest(allies_visible())) < 0.6

def heal_self_ok(s):
    return ability_ready(s) and slot_is_heal(s) and health() < max_health() * 0.5

def out_of_reach(t):
    return (i_am_ranged() and dist_to(t) > 3) or ((not i_am_ranged()) and dist_to(t) > 1)

def fight(t):
    set_team_target(t)
    if i_am_ranged() and enemies_within(1) > 0 and can_move() and health() < max_health() * 0.6:
        move_away_from(unit_position(t))
    if stun_ok(0, t):
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        elif slot_radius(0) > 0:
            cast_at_tile(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    elif stun_ok(1, t):
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        elif slot_radius(1) > 0:
            cast_at_tile(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    elif heal_ally_ok(0):
        cast_at_unit(0, weakest(allies_visible()))
    elif heal_ally_ok(1):
        cast_at_unit(1, weakest(allies_visible()))
    elif heal_self_ok(0):
        cast_self(0)
    elif heal_self_ok(1):
        cast_self(1)
    elif shield_ok(0):
        cast_self(0)
    elif shield_ok(1):
        cast_self(1)
    elif dmg_ok(1, t):
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        elif slot_is_aoe(1):
            cast_at_tile(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    elif dmg_ok(0, t):
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        elif slot_is_aoe(0):
            cast_at_tile(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    if out_of_reach(t):
        if can_move():
            move_towards(unit_position(t))
    attack(t)
    if not can_attack():
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(t)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(t)

