    end_turn()

# ---- shopping (role-based stats) ----
if (not alive()) or contains(spawn_region(ally()), position()):
    if gold() >= 30:
        if round_number() < 250:
            buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
        elif i_am(champ_heart_of_ruin()):
            buy(shard_of(family_bruiser(), stat_health()), floor(gold() / 30))
        elif i_am(champ_vesper_vale()) or i_am(champ_vendetta()):
            buy(shard_of(family_power(), stat_strength()), floor(gold() / 30))
        elif i_am(champ_marcella()) or i_am(champ_ryth()) or i_am(champ_prism()) or i_am(champ_cassi_issac()) or i_am(champ_tavi()) or i_am(champ_stellar()):
            buy(shard_of(family_power(), stat_focus()), floor(gold() / 30))
        else:
            buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

if not alive():
    end_turn()
if channeling():
    end_turn()

if i_am(champ_heart_of_ruin()):
    set_priority(3)
else:
    set_priority(1)

keep wallring = ring(walls(), 1)
keep monogroup = group_tiles(monolith_tiles())
keep safealt = minus(altars(), ring(monolith_tiles(), 5))
keep altadj = minus(ring(safealt, 1), altars())
keep altadjall = minus(ring(altars(), 1), altars())
keep campset = minus(camp_spawn_tiles(), monogroup)
