        move_away_from(unit_position(foe))
        end_turn()
if hp < 0.4 and not in_danger() and not contains(spawn_region(ally()), me):
    recall()
    end_turn()
if hp < 0.9 and contains(spawn_region(ally()), me) and nfoes == 0:
    end_turn()

# ---- tribute ----
if gems() >= 35 or (gems() >= 10 and nfoes > 0) or (gems() > 0 and round_number() > 1900):
    let adjalt = first(filter(altars(), within(1, me)))
    if exists(adjalt):
        tribute(adjalt)
        end_turn()
    let alt = closest(altadj)
    if exists(alt):
        if nfoes == 0 or gems() >= 10:
            move_towards(alt)
            end_turn()
    else:
        let alt2 = closest(altadjall)
        if exists(alt2):
            if nfoes == 0 or gems() >= 10:
