        end_turn()

# ---- capture ----
let cap = closest(capturable_spawns())
if exists(cap):
    move_towards(cap)
    end_turn()

# ---- camps (ward the bush beside us while farming; abilities on camps) ----
let camp = nearest(camps_visible())
if exists(camp):
    let mono = closest(monolith_tiles())
    let monook = round_number() >= 1000 and allies_within(5) >= 2 and hp > 0.6
    if distance(unit_position(camp), mono) > 6 or monook:
        if nfoes == 0 and distance(me, unit_position(camp)) <= 4:
            let wb = first(filter(bushset, within(2, me)))
            if exists(wb):
                place_ward(wb)
        if can_attack() and (distance(me, unit_position(camp)) <= 1 or (i_am_ranged() and distance(me, unit_position(camp)) <= 3)):
            attack(camp)
            if ability_ready(0) and slot_is_reset(0):
                cast_self(0)
                attack(camp)
            elif ability_ready(1) and slot_is_reset(1):
                cast_self(1)
                attack(camp)
            camp_abil(0, camp)
            camp_abil(1, camp)
            end_turn()

let near = closest(campset)
let richc = closest(richset)
if exists(richc) and distance(me, richc) <= distance(me, near) + 6:
    claim(richc)
    move_towards(richc)
    end_turn()
if exists(near):
    claim(near)
    move_towards(near)
    end_turn()
if turns_idle() > 3:
    move_towards(closest(camp_spawn_tiles()))

# roles-v2: per-champion jobs on top of roles-v1.
#  SUPPORT (Vesper Vale / Willow): heals the weakest visible ally in range; otherwise farms.
#  HUNTER (Heart of Ruin / Varg / Vendetta): closes on a nearby enemy champion while healthy.
#  COLLECTOR (Ren / Tavi): when no camp is in reach, walks to the nearest gold cluster
#    (gold_cluster_tiles: no damage, 20 gold each) and holds there to capture it; gold buys shards.
#  FARMER (everyone else): unchanged camp and tribute behaviour.
# Ability casting helpers are unchanged from roles-v1.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
# monolith groups never change: one group_tiles() per game (fuel; bot-session check)
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
# per-champion roles
let support = i_am(champ_vesper_vale()) or i_am(champ_willow())
let hunter = i_am(champ_heart_of_ruin()) or i_am(champ_varg()) or i_am(champ_vendetta())
let collector = i_am(champ_ren()) or i_am(champ_tavi())
# one enemies_visible() query per turn, reused below (no move happens before its last use)
let foes = enemies_visible()
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health; recall only when no enemy champion is close
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate: a long retreat's dash search can push the turn past 100k
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: cast damage/stun at a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0):
            cast_at_unit(0, near_foe)
        if ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1):
            cast_at_unit(1, near_foe)

# SUPPORT role: heal the weakest visible ally in heal range before fighting
if support:
    let mate = weakest( allies_visible() )
    if exists(mate) and unit_health_frac(mate) < 0.6:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(mate)) <= slot_range(0):
            cast_at_unit(0, mate)
        elif ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(mate)) <= slot_range(1):
            cast_at_unit(1, mate)

let enemy = weakest( filter( foes, in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    # attack reset: a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# HUNTER role: nothing in attack range, healthy, and an enemy champion is close: close the gap
if hunter and health() > 0.6 * max_health() and fuel_remaining() > 50000:
    let prey = nearest( foes )
    if exists(prey) and distance(position(), unit_position(prey)) <= 6 and not contains( spawn_region(enemy()), unit_position(prey) ):
        move_towards( unit_position(prey) )
        end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach; else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# COLLECTOR role: no camp in reach, so take a nearby gold cluster (no damage, 20 gold) and hold it
if collector and not hunter and not support and gems() < 20:
    let gold_goal = closest( gold_cluster_tiles() )
    if exists(gold_goal) and distance(position(), gold_goal) <= 12:
        if contains( gold_cluster_tiles(), position() ):
            end_turn()
        move_towards(gold_goal)
        end_turn()

# nothing tributed by round 800: go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group not yet cleared: walk to the nearest living camp instead
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# dash toward a far camp goal only with fuel to spare
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# PLAN (abilities-first single champion):
# - Draft the top-team champions (Vesper Vale, Heart of Ruin, Marcella, Vendetta, Ryth).
# - Fight micro, every turn an enemy is near:
#   1. Open with a stun. Dash stunners dash onto the target. Area stuns are cast at the
#      target's tile. Single-target stuns are cast at the unit.
#   2. Shield myself when the target is close. Heal myself when hurt.
#   3. Basic attack, then self-cast a reset at once, then attack again.
#   4. Spend non-stun damage or AoE abilities after the burst (AoE at the target tile).
#   5. Close the gap with a non-stun dash. A hurt ranged champion steps away from an
#      adjacent melee enemy.
#   Focus the team target when it is close; otherwise pick the nearest enemy and name it.
# - Survival: at low HP step away from enemies first, recall only when not in danger.
#   Heal on spawn.
# - Farming: capture cleared groups, hit visible camps (never the monolith) and use
#   damage abilities on them. Walk to a rich camp if it is only a few tiles farther
#   than the nearest one.
# - Gems: tribute at once if an altar is adjacent and an enemy is near. Otherwise carry
#   to an altar (prefer altars away from monoliths) once the bag is big enough.

def dist(t):
    return distance(position(), unit_position(t))

def reach(t):
    return (dist(t) <= 1) or (i_am_ranged() and dist(t) <= 3)

