    if gold() >= 30:
        if round_number() < 300:
            buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
        else:
            buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

def fight(t):
    set_team_target(t)
    if ability_ready(0) and slot_stun(0) > 0 and dist(t) <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        elif slot_radius(0) > 0:
            cast_at_tile(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    elif ability_ready(1) and slot_stun(1) > 0 and dist(t) <= slot_range(1) + slot_radius(1):
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        elif slot_radius(1) > 0:
            cast_at_tile(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    if ability_ready(0) and slot_is_shield(0) and dist(t) <= 3:
        cast_self(0)
    if ability_ready(1) and slot_is_shield(1) and dist(t) <= 3:
        cast_self(1)
    if ability_ready(0) and slot_is_heal(0) and health() < 0.7 * max_health():
        cast_self(0)
    if ability_ready(1) and slot_is_heal(1) and health() < 0.7 * max_health():
        cast_self(1)
    if i_am_ranged() and dist(t) <= 1 and can_move() and health() < 0.5 * max_health():
        move_away_from(unit_position(t))
    if can_attack() and reach(t):
        attack(t)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
        if ability_ready(1) and slot_is_reset(1):
            cast_self(1)
        if can_attack() and reach(t):
            attack(t)
    if ability_ready(0) and slot_stun(0) == 0 and (slot_is_damage(0) or slot_is_aoe(0)) and dist(t) <= slot_range(0) + slot_radius(0):
