        else:
            cast_at_unit(1, t)
    if can_move() and not (reach(t)):
        if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0 and dist(t) <= slot_range(0) + 2:
            dash_towards(0, unit_position(t))
        elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0 and dist(t) <= slot_range(1) + 2:
