# PLAN (items & stats axis):
# - Draft: Heart of Ruin (stun-dash tank/opener), Vesper Vale (reset carry), Marcella and Ryth
#   (ability casters), Vendetta (reset diver).
# - Per-champion builds, bought by round phase:
#     * Rounds < 300: Treasure shards, so farming pays more early.
#     * Marcella / Ryth: Power FOCUS, which scales their abilities.
#     * Vesper Vale: Power STRENGTH, stacking basic damage on the reset carry.
#     * HoR / Vendetta / others: Bruiser STRENGTH, then Durability HEALTH after round 1100
#       to survive late fights.
# - Shopping trips: with lots of gold, few gems and no enemy in sight, recall home and spend.
#   Also spend while dead and on spawn. Gold sitting in pockets is wasted stats.
# - Combat micro: attack, then self-cast the reset, then attack again. Open with stun abilities.
#   Shield in fights. Ranged champions stay at range.
#   HoR acts first (priority) to land the opener.
# - Macro: tribute at 25 gems at safe altars (outside monolith reach). Prefer rich camps a few
#   tiles farther. Avoid monoliths.

def shop():
  if gold() >= 30:
    if round_number() < 300:
      buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
    elif i_am(champ_marcella()) or i_am(champ_ryth()):
      buy(shard_of(family_power(), stat_focus()), floor(gold() / 30))
    elif i_am(champ_vesper_vale()):
      buy(shard_of(family_power(), stat_strength()), floor(gold() / 30))
    elif round_number() > 1100:
      buy(shard_of(family_durability(), stat_health()), floor(gold() / 30))
    else:
      buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

def use_ability(s, foe, d):
  if ability_ready(s):
    if slot_is_reset(s):
      if not can_attack():
        cast_self(s)
    elif slot_is_shield(s):
      cast_self(s)
    elif slot_is_heal(s):
      if health() < max_health() * 0.7:
        cast_self(s)
    elif slot_is_dash(s):
      if slot_stun(s) > 0 and d <= slot_range(s) + 1:
        dash_towards(s, unit_position(foe))
      elif d > 1 and d <= 3 and not i_am_ranged():
        dash_towards(s, unit_position(foe))
    elif d <= slot_range(s) + slot_radius(s):
      cast_at_unit(s, foe)

def go_tribute(a):
  if distance(position(), a) <= 1:
    tribute(a)
  else:
    move_towards(a)

if is_draft():
  let pool = unpicked_champions()
  if available(pool, champ_heart_of_ruin()):
    pick(champ_heart_of_ruin())
  elif available(pool, champ_vesper_vale()):
    pick(champ_vesper_vale())
  elif available(pool, champ_marcella()):
    pick(champ_marcella())
  elif available(pool, champ_vendetta()):
    pick(champ_vendetta())
  elif available(pool, champ_ryth()):
    pick(champ_ryth())
  else:
    pick(random_champion(pool))
  end_turn()

