  shop()
  if hp < 0.9 and enemies_within(3) == 0:
    end_turn()

let foe = nearest(enemies_visible())
let d = distance(position(), unit_position(foe))
let alt = closest(safealt)
let altany = closest(altars())

# retreat when low
if hp < 0.35:
  if exists(foe) and d <= 5:
    move_away_from(unit_position(foe))
  elif in_danger():
    move_towards(closest(spawn_region(ally())))
  else:
    recall()
  end_turn()

# carrying with enemy near: tribute immediately if beside an altar
if gems() >= 8 and exists(foe) and d <= 6:
  if exists(altany):
    if distance(position(), altany) <= 1:
      tribute(altany)
      end_turn()

# fight
if exists(foe) and d <= 6 and (hp >= 0.5 or d <= 2):
  if not exists(team_target()):
    set_team_target(foe)
  if can_attack() and (d <= 1 or (i_am_ranged() and d <= 3)):
    attack(foe)
  use_ability(0, foe, d)
  use_ability(1, foe, d)
  if can_attack() and (d <= 1 or (i_am_ranged() and d <= 3)):
    attack(foe)
  if i_am_ranged():
    if d > 3:
      move_towards(unit_position(foe))
  elif d > 1:
    move_towards(unit_position(foe))
  end_turn()

# tribute a full bag
if gems() >= 25 or (gems() > 0 and round_number() > 1900):
  if exists(alt):
    go_tribute(alt)
  elif exists(altany):
    go_tribute(altany)
  end_turn()

# shopping trip: convert gold into stats
if gold() >= 180 and gems() < 10 and not onspawn and not exists(foe):
  if not in_danger():
    recall()
    end_turn()

# capture cleared camps
let caps = capturable_spawns()
if count(caps) > 0:
  let cap = closest(caps)
  if exists(cap):
    if distance(position(), cap) > 0:
      move_towards(cap)
    end_turn()

# fight camps in range (never the monolith)
let camp = weakest(filter(camps_visible(), in_attack_range()))
if exists(camp):
  if not contains(monozone, unit_position(camp)):
    attack(camp)
    if ability_ready(0) and slot_is_damage(0):
      cast_at_unit(0, camp)
    if ability_ready(1) and slot_is_damage(1):
      cast_at_unit(1, camp)
    if ability_ready(0) and slot_is_reset(0) and not can_attack():
      cast_self(0)
    if ability_ready(1) and slot_is_reset(1) and not can_attack():
      cast_self(1)
    if can_attack():
      attack(camp)
    end_turn()

# choose a camp: rich if only a bit farther, else nearest
let resp = respawning_visible_spawns()
let nearg = closest(minus(minus(camp_spawn_tiles(), monozone), resp))
let richg = closest(minus(richsafe, resp))
if exists(richg) and distance(position(), richg) <= distance(position(), nearg) + 6:
  move_towards(richg)
elif exists(nearg):
  move_towards(nearg)
elif gems() > 0 and exists(altany):
  go_tribute(altany)
